<script setup>import PartnerLayout from '@/Layouts/PartnerLayout.vue';import Pagination from '@/Components/Partner/Pagination.vue';import FormErrors from '@/Components/Partner/FormErrors.vue';import {Link,useForm} from '@inertiajs/vue3';defineProps({tickets:Object,customers:Array,teams:Array});const form=useForm({customer_uuid:'',team_uuid:'',subject:'',priority:'normal',message:''});</script><template><PartnerLayout title="Support requests"><form class="form-card mb-6" @submit.prevent="form.post(route('partner.support.store'))"><h2 class="text-xl font-bold">Request support for a client</h2><FormErrors :errors="form.errors"/><div class="form-grid"><label>Client<select v-model="form.customer_uuid" required><option value="">Choose client</option><option v-for="client in customers" :key="client.uuid" :value="client.uuid">{{ client.name }}</option></select></label><label>Support team<select v-model="form.team_uuid" required><option value="">Choose team</option><option v-for="team in teams" :key="team.uuid" :value="team.uuid">{{ team.name }}</option></select></label><label>Subject<input v-model="form.subject" required minlength="5" maxlength="255"/></label><label>Priority<select v-model="form.priority"><option v-for="priority in ['low','normal','high','urgent']" :key="priority">{{ priority }}</option></select></label></div><label>Request details<textarea v-model="form.message" required minlength="10" maxlength="20000" rows="5"/></label><button class="form-button" :disabled="form.processing||!customers.length||!teams.length">Create support request</button></form><div class="space-y-3"><Link v-for="ticket in tickets.data" :key="ticket.uuid" :href="route('partner.support.show',ticket.uuid)" class="block rounded-xl bg-white p-5"><strong>{{ ticket.ticket_number }} ? {{ ticket.subject }}</strong><p class="mt-2 text-sm">{{ ticket.customer.name }} ? {{ ticket.status }} ? {{ ticket.priority }}</p></Link><p v-if="!tickets.data.length">No support requests yet.</p></div><Pagination :page="tickets"/></PartnerLayout></template>
